function b64ToBuffer(b64){
  var bin=atob(b64),len=bin.length,buf=new Uint8Array(len);
  for(var i=0;i<len;i++)buf[i]=bin.charCodeAt(i);
  return buf.buffer;
}
function iconResponse(b64){
  return new Response(b64ToBuffer(b64),{headers:{'Content-Type':'image/png','Cache-Control':'public, max-age=86400'}});
}

self.addEventListener('install',function(e){
  e.waitUntil(
    caches.open(CACHE).then(function(cache){
      return cache.addAll(ASSETS).then(function(){
        cache.put(BASE+'/icon-192.png',iconResponse(ICON192_B64));
        cache.put(BASE+'/icon-512.png',iconResponse(ICON512_B64));
      });
    }).then(function(){return self.skipWaiting();})
  );
});

self.addEventListener('activate',function(e){
  e.waitUntil(
    caches.keys().then(function(keys){
      return Promise.all(keys.filter(function(k){return k!==CACHE;}).map(function(k){return caches.delete(k);}));
    }).then(function(){return self.clients.claim();})
  );
});

self.addEventListener('fetch',function(e){
  var url=e.request.url;
  if(url.endsWith('/icon-192.png')){e.respondWith(iconResponse(ICON192_B64));return;}
  if(url.endsWith('/icon-512.png')){e.respondWith(iconResponse(ICON512_B64));return;}
  e.respondWith(
    caches.match(e.request).then(function(r){
      return r||fetch(e.request);
    })
  );
});
